using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondThirdMaximum;
internal sealed class PhysicalDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original physical banks at equal second and third maxima",
        H("Every occurrence and the literal fresh ear"),
        Blocks(
            Paragraph(Text("The U,V,W,X physical offsets are exactly 0,d,d+c,d+c+b, with positive chain lengths d-1,c-1,b-1,a-1 and terminals d-1,d+c-1,d+c+b-1,k-1, where k=a+b+c+d. Substituting the hypothesis b=c=s does not rotate, reflect, or change the seed. The terminal order is W minus, X minus, U minus, V minus. Every bit decoder lists actual physical labels in increasing exponent order.")),
            Paragraph(Text("Bank 0 contains every U head. Bank 1 contains V[p], W[h], X[w]. Bank 2 contains the complements V[x-1-p], W[R-h], X[(x/2-1)-w]. Bank 3 contains V[(z/2-1)-(x-1)] and W[x-2]. Here R=z/2-x+1 and h=xH+e. The implementation realizes W[h] as the possible physical bit 0 plus a shifted high decoder on H; its complement contains the other choice of bit 0 plus the high decoder complement. W[x-2] is exactly exponents 1 through a-1. V is split into its a low bits and the untouched high block. XOR is used only for complements inside a proved full low-bit stock, and no subtraction of arbitrary capacities stands in for a bit selection.")),
            Paragraph(Text("The V, W and X partition proofs use existing chamberLabels_split, chamberLabels_full and the canonical original-chain inventory. As multisets the four banks plus the four distinct original terminals equal range k, so each original occurrence appears once. If cp,ch,cw are the selected popcounts, the positive-bank counts are d-1, cp+ch+cw, s+a-1-cp-ch-cw, and s-2; they add to k-4. The Lean inventory proves this at the label level rather than assuming these numerical counts.")),
            Paragraph(Text("PacketNormalForm.chain_values, source_totals and native_masses provide the actual centered recurrence, all native terminal masses and the independent complete totals. The first and second bank endpoints have doubled old heights B+K-2A and 2hL+2pB+B-nK. The corresponding enlarged heights are SU+SW-2A and 2hSV+2pSU+SU-nSW. The endpoint after U minus is recovered from the actual last suffix and the complete zero total: it is xB-(x-1)L in the old row and xSU-(x-1)SV in the new row. This also avoids assuming a total from local seam inequalities.")),
            Paragraph(Text("The enlarged first bank begins with the one new physical label k. Its value is A by chain_values/source_totals. Thus the enlarged natural-label word is literally insertAt k oldWord 0. All positive bank increments are nonnegative in both rows. The four_strip library theorem converts the seam bounds, native negative jumps and complete totals into every prefix bound, including empty and overlong takes. Finally actual_nat_joint_iff converts exactly these natural physical labels to one Fin k permutation and its same-cut earWord. No separate source permutation or enlarged-word witness is substituted.")),
            Paragraph(Text("The mathematics here concerns labeled centered modular words. Multiplication by two in the odd residue ring explains the dyadic chains, but no group action on banks, transitivity, orbit classification, or general Circle result is inferred from this construction. The original seed and physical labels determine both centered rows throughout the construction."))), []));
}
